func (s *Store) GamaSearchHistory(ctx context.Context, query string, favoritesOnly bool) ([]GamaHistoryItem,error) {
 if err:=s.ensureDB(); err!=nil { return nil,err }
 rows,err:=s.db.conn.QueryContext(ctx,`SELECT c.id,c.title, f.chat_id IS NOT NULL
 FROM chats c LEFT JOIN gama_favorites f ON c.id=f.chat_id
 WHERE (?=0 OR f.chat_id IS NOT NULL)
 AND (?='' OR instr(lower(c.title),lower(?))>0 OR EXISTS (
 SELECT 1 FROM messages m WHERE m.chat_id=c.id AND m.role IN ('user','assistant') AND instr(lower(m.content),lower(?))>0))
 ORDER BY (f.chat_id IS NOT NULL) DESC, c.created_at DESC LIMIT 100`,favoritesOnly,query,query,query)
 if err!=nil { return nil,err }
 defer rows.Close()
 result:=make([]GamaHistoryItem,0)
 for rows.Next() {
  var item GamaHistoryItem
  if err:=rows.Scan(&item.ID,&item.Title,&item.Favorite);err!=nil{return nil,err}
  result=append(result,item)
 }
