}

func (s *Store) GamaSetFavorite(id string, favorite bool) error {
 if err:=s.ensureDB();err!=nil{return err}
 if favorite {
  _,err:=s.db.conn.Exec("INSERT OR IGNORE INTO gama_favorites (chat_id) VALUES (?)",id)
