func (s *Server) gamaHistoryEnabled() (bool,error) {
 settings,err:=s.Store.Settings()
 return settings.GamaModules & store.GamaHistory != 0,err
}
func (s *Server) gamaHistory(w http.ResponseWriter,r *http.Request) error {
 enabled,err:=s.gamaHistoryEnabled()
 if err!=nil{return err}
 if !enabled {http.Error(w,"Gama history disabled",http.StatusForbidden);return nil}
 q:=strings.TrimSpace(r.URL.Query().Get("q"))
 if utf8.RuneCountInString(q)>200{return fmt.Errorf("query too long")}
 ctx,cancel:=context.WithTimeout(r.Context(),3*time.Second)
 defer cancel()
 items,err:=s.Store.GamaSearchHistory(ctx,q,r.URL.Query().Get("favorites")=="1")
 if err!=nil{return err}
 w.Header().Set("Content-Type","application/json")
 w.Header().Set("Cache-Control","no-store")
 return json.NewEncoder(w).Encode(items)
}
func (s *Server) gamaFavorite(w http.ResponseWriter,r *http.Request) error {
 enabled,err:=s.gamaHistoryEnabled()
 if err!=nil{return err}
 if !enabled {http.Error(w,"Gama history disabled",http.StatusForbidden);return nil}
 var req struct {ID string `json:"id"`; Favorite *bool `json:"favorite"`}
 if err:=json.NewDecoder(http.MaxBytesReader(w,r.Body,4096)).Decode(&req);err!=nil{return err}
 if req.ID==""||len(req.ID)>100||req.Favorite==nil{return fmt.Errorf("invalid favorite request")}
 if err:=s.Store.GamaSetFavorite(req.ID,*req.Favorite);err!=nil{return err}
 w.WriteHeader(http.StatusNoContent)
 return nil
}

