import { useContext, useEffect, useRef, useState } from "react";
import { useNavigate } from "@tanstack/react-router";
import { API_BASE } from "@/lib/config";
import { GamaContext, GAMA_HISTORY } from "./GamaModules";

type Item = {id:string;title:string;favorite:boolean};
export function HistoryPanel() {
 const flags=useContext(GamaContext);
 return (flags & GAMA_HISTORY)!==0 ? <HistoryBody/> : null;
}
function HistoryBody() {
 const navigate=useNavigate();
 const [open,setOpen]=useState(false);
 const [query,setQuery]=useState("");
 const [favorites,setFavorites]=useState(false);
 const [items,setItems]=useState<Item[]>([]);
 const [busy,setBusy]=useState(false);
 const [error,setError]=useState("");
 const abort=useRef<AbortController|null>(null);
 useEffect(()=>()=>abort.current?.abort(),[]);
 const request=async (q:string,f:boolean, favorite?:Item)=>{
  abort.current?.abort();
  const c=new AbortController();abort.current=c;setBusy(true);setError("");
  try{
   if(favorite){
    const response=await fetch(API_BASE+"/api/v1/gama/favorite",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:favorite.id,favorite:!favorite.favorite}),signal:c.signal});
    if(!response.ok)throw Error("favorite");
   }
   const params=new URLSearchParams({q,favorites:f?"1":"0"});
   const response=await fetch(API_BASE+"/api/v1/gama/history?"+params,{signal:c.signal,cache:"no-store"});
   if(!response.ok)throw Error("history");
   const result=await response.json();
   if(!c.signal.aborted)setItems(Array.isArray(result)?result:[]);
  }catch{if(!c.signal.aborted)setError("Não foi possível consultar ou alterar o histórico.");}
  finally{if(!c.signal.aborted)setBusy(false);}
 };
 return <div className="px-5 pb-2 text-xs text-neutral-500 dark:text-neutral-400" onKeyDown={e=>e.stopPropagation()}>
  <button type="button" aria-expanded={open} onClick={()=>{if(open){abort.current?.abort();setBusy(false);setOpen(false);setItems([]);setError("");}else{setOpen(true);void request(query,favorites);}}}>Buscar conversas e favoritos</button>
  {open&&<div className="mt-2 rounded-lg border border-neutral-200 dark:border-neutral-700 p-3 space-y-2">
   <form className="flex gap-2" onSubmit={e=>{e.preventDefault();void request(query,favorites);}}>
    <input aria-label="Buscar conversas" maxLength={200} value={query} onChange={e=>setQuery(e.target.value)} placeholder="Título ou mensagem" className="flex-1 min-w-0 bg-transparent"/>
    <button type="submit" disabled={busy}>Buscar</button>
   </form>
   <label><input type="checkbox" checked={favorites} disabled={busy} onChange={e=>{setFavorites(e.target.checked);void request(query,e.target.checked);}}/> Somente favoritos</label>
   {error&&<p role="alert">{error}</p>}
   {busy&&<p role="status">Consultando…</p>}
   {!busy&&!error&&!items.length&&<p>Nenhuma conversa encontrada.</p>}
   <div className="max-h-48 overflow-auto space-y-2">{items.map(item=><div key={item.id} className="flex gap-2 justify-between">
     <button type="button" className="text-left truncate" onClick={()=>{setOpen(false);void navigate({to:"/c/$chatId",params:{chatId:item.id}});}}>{item.title||"Sem título"}</button>
     <button type="button" disabled={busy} aria-label={item.favorite?"Remover favorito":"Favoritar"} aria-pressed={item.favorite} onClick={()=>void request(query,favorites,item)}>{item.favorite?"★":"☆"}</button>
   </div>)}</div>
   <p>Até 100 resultados. Busca local, sem indexação permanente.</p>
  </div>}
 </div>;
}
